214: // We will also define GoogleOnceType, GOOGLE_ONCE_INIT, and
215: // GoogleOnceInit, which are portable versions of pthread_once_t,
216: // PTHREAD_ONCE_INIT, and pthread_once.
217: 
218: // Now the implementation of Mutex for various systems
219: #if defined(NO_THREADS)
220: 
221: // When we don't have threads, we can be either reading or writing,
222: // but not both.  We can have lots of readers at once (in no-threads
223: // mode, that's most likely to happen in recursive function calls),
224: // but only one writer.  We represent this by having mutex_ be -1 when
225: // writing and a number > 0 when reading (and 0 when no lock is held).
226: //
227: // In debug mode, we assert these invariants, while in non-debug mode
228: // we do nothing, for efficiency.  That's why everything is in an
229: // assert.
230: 
231: Mutex::Mutex() : mutex_(0) { }
232: Mutex::Mutex(base::LinkerInitialized) : mutex_(0) { }
233: Mutex::~Mutex()            { assert(mutex_ == 0); }
234: void Mutex::Lock()         { assert(--mutex_ == -1); }
235: void Mutex::Unlock()       { assert(mutex_++ == -1); }
236: #ifdef GMUTEX_TRYLOCK
237: bool Mutex::TryLock()      { if (mutex_) return false; Lock(); return true; }
238: #endif
239: void Mutex::ReaderLock()   { assert(++mutex_ > 0); }
240: void Mutex::ReaderUnlock() { assert(mutex_-- > 0); }
241: 
242: typedef int GoogleOnceType;
243: const GoogleOnceType GOOGLE_ONCE_INIT = 0;
244: inline int GoogleOnceInit(GoogleOnceType* once_control,
245:                           void (*init_routine)(void)) {
246:   if ((*once_control)++ == 0)
247:     (*init_routine)();
248:   return 0;
249: }
250: 
251: #elif defined(_WIN32) || defined(__CYGWIN32__) || defined(__CYGWIN64__)
252: 
253: Mutex::Mutex() : destroy_(true) {
254:   InitializeCriticalSection(&mutex_);
255:   SetIsSafe();
256: }
257: Mutex::Mutex(base::LinkerInitialized) : destroy_(false) {
258:   InitializeCriticalSection(&mutex_);
259:   SetIsSafe();
260: }
261: Mutex::~Mutex()            { if (destroy_) DeleteCriticalSection(&mutex_); }
262: void Mutex::Lock()         { if (is_safe_) EnterCriticalSection(&mutex_); }
263: void Mutex::Unlock()       { if (is_safe_) LeaveCriticalSection(&mutex_); }
264: #ifdef GMUTEX_TRYLOCK
265: bool Mutex::TryLock()      { return is_safe_ ?
266:                                  TryEnterCriticalSection(&mutex_) != 0 : true; }
267: #endif
268: void Mutex::ReaderLock()   { Lock(); }      // we don't have read-write locks
269: void Mutex::ReaderUnlock() { Unlock(); }
270: 
271: // We do a simple spinlock for pthread_once_t.  See
272: //    http://www.ddj.com/cpp/199203083?pgno=3
273: #ifdef INTERLOCKED_EXCHANGE_NONVOLATILE
274: typedef LONG GoogleOnceType;
275: #else
276: typedef volatile LONG GoogleOnceType;
277: #endif
278: const GoogleOnceType GOOGLE_ONCE_INIT = 0;
279: inline int GoogleOnceInit(GoogleOnceType* once_control,
280:                           void (*init_routine)(void)) {
281:   while (1) {
282:     LONG prev = InterlockedCompareExchange(once_control, 1, 0);
283:     if (prev == 2) {            // We've successfully initted in the past.
284:       return 0;
285:     } else if (prev == 0) {     // No init yet, but we have the lock.
286:       (*init_routine)();
287:       InterlockedExchange(once_control, 2);
288:       return 0;
289:     } else {                    // Someone else is holding the lock, so wait.
290:       assert(1 == prev);
291:       Sleep(1);                 // sleep for 1ms
292:     }
293:   }
294:   return 1;                     // unreachable
295: }
296: 
297: #elif defined(HAVE_PTHREAD) && defined(HAVE_RWLOCK)
298: 
299: #define SAFE_PTHREAD(fncall)  do {   /* run fncall if is_safe_ is true */  \
300:   if (is_safe_ && fncall(&mutex_) != 0) abort();                           \
301: } while (0)
302: 
303: Mutex::Mutex() : destroy_(true) {
304:   SetIsSafe();
305:   if (is_safe_ && pthread_rwlock_init(&mutex_, NULL) != 0) abort();
306: }
307: Mutex::Mutex(base::LinkerInitialized) : destroy_(false) {
308:   SetIsSafe();
309:   if (is_safe_ && pthread_rwlock_init(&mutex_, NULL) != 0) abort();
310: }
311: Mutex::~Mutex()       { if (destroy_) SAFE_PTHREAD(pthread_rwlock_destroy); }
312: void Mutex::Lock()    { SAFE_PTHREAD(pthread_rwlock_wrlock); }
313: void Mutex::Unlock()  { SAFE_PTHREAD(pthread_rwlock_unlock); }
314: #ifdef GMUTEX_TRYLOCK
315: bool Mutex::TryLock()      { return is_safe_ ?
316:                                pthread_rwlock_trywrlock(&mutex_) == 0 : true; }
317: #endif
318: void Mutex::ReaderLock()   { SAFE_PTHREAD(pthread_rwlock_rdlock); }
319: void Mutex::ReaderUnlock() { SAFE_PTHREAD(pthread_rwlock_unlock); }
320: #undef SAFE_PTHREAD
321: 
322: typedef pthread_once_t GoogleOnceType;
323: const GoogleOnceType GOOGLE_ONCE_INIT = PTHREAD_ONCE_INIT;
324: inline int GoogleOnceInit(GoogleOnceType* once_control,
325:                           void (*init_routine)(void)) {
326:   return pthread_once(once_control, init_routine);
327: }
328: 
329: #elif defined(HAVE_PTHREAD)
330: 
331: #define SAFE_PTHREAD(fncall)  do {   /* run fncall if is_safe_ is true */  \
332:   if (is_safe_ && fncall(&mutex_) != 0) abort();                           \
333: } while (0)
334: 
335: Mutex::Mutex() : destroy_(true) {
336:   SetIsSafe();
337:   if (is_safe_ && pthread_mutex_init(&mutex_, NULL) != 0) abort();
338: }
339: Mutex::Mutex(base::LinkerInitialized) : destroy_(false) {
340:   SetIsSafe();
341:   if (is_safe_ && pthread_mutex_init(&mutex_, NULL) != 0) abort();
342: }
343: Mutex::~Mutex()       { if (destroy_) SAFE_PTHREAD(pthread_mutex_destroy); }
344: void Mutex::Lock()    { SAFE_PTHREAD(pthread_mutex_lock); }
345: void Mutex::Unlock()  { SAFE_PTHREAD(pthread_mutex_unlock); }
346: #ifdef GMUTEX_TRYLOCK
347: bool Mutex::TryLock() { return is_safe_ ?
348:                                pthread_mutex_trylock(&mutex_) == 0 : true; }
349: #endif
350: void Mutex::ReaderLock()   { Lock(); }
351: void Mutex::ReaderUnlock() { Unlock(); }
352: #undef SAFE_PTHREAD
353: 
354: typedef pthread_once_t GoogleOnceType;
355: const GoogleOnceType GOOGLE_ONCE_INIT = PTHREAD_ONCE_INIT;
356: inline int GoogleOnceInit(GoogleOnceType* once_control,
357:                           void (*init_routine)(void)) {
358:   return pthread_once(once_control, init_routine);
359: }
